package com.gestourant.order; import com.gestourant.catalog.Product; import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="order_items") public class OrderItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="order_id") private RestaurantOrder order; @ManyToOne(optional=false) @JoinColumn(name="product_id") private Product product; @Column(nullable=false) private Integer quantity; @Column(name="unit_price",nullable=false,precision=12,scale=2) private BigDecimal unitPrice; @Column(nullable=false,precision=12,scale=2) private BigDecimal subtotal; protected OrderItem(){} public OrderItem(RestaurantOrder o,Product p,int q){order=o;product=p;quantity=q;unitPrice=p.getPrice();subtotal=unitPrice.multiply(BigDecimal.valueOf(q));} public Long getId(){return id;} public Product getProduct(){return product;} public Integer getQuantity(){return quantity;} public BigDecimal getUnitPrice(){return unitPrice;} public BigDecimal getSubtotal(){return subtotal;} }
